/**
 * The six Release 1 settings frames (the five of canvas version
 * 1794789966-7cde, and advanced from the canvas the owner shared before round
 * 7; the display frame's ring tile as redrawn in version 1794819772-c22a), for
 * pixel comparison of the settings panel. From round 2.8 the display frame is
 * the Release 2 display frame (canvas version 1794927010-cb9d), compared whole,
 * 1220 px tall: as drawn with ocean depth chosen, or with digits chosen (the
 * default) and so without the ocean depth options box. With every mode's tile
 * but digits, ring, timeline and analog a test mode's from round 2.10, the frame
 * is compared with the test-modes switch on, its interstellar tile and its note
 * included. Two parts are left out until they exist: the picture-in-picture
 * switch (round 2.12), and the downloaded modes list (the test browser
 * downloads none). The "change opens settings on it" frame is the
 * same panel with the fullscreen switch on and its row outlined. Each is the frame's own
 * panel markup; its colours are filled in from a palette computed by the
 * frame's own formulas, and its fonts are mapped to the site's files:
 * "Archivo" to the trimmed default font, each other family in the font grid
 * to the site's name preview of that font, and in the advanced frame "IBM
 * Plex Mono" (the custom CSS editor) to the site's IBM Plex Mono at 400.
 *
 * From round 2.1 the appearance frame is Release 2's ("release 2 settings:
 * appearance (animation speed, low power)"): the Release 1 frame with those two
 * rows added before its reset button, 1160 px tall; nothing else differs.
 *
 * Two owner rules make the site differ from the frames, and are applied to
 * the reference: the footer's source code link stays hidden until the
 * owner says so (privacy, terms and feedback show); Lexend is not offered
 * (no tabular figures).
 */

export interface Palette {
  readonly bg: string;
  readonly text: string;
  readonly accent: string;
  readonly muted: string;
  readonly faint: string;
  readonly track: string;
  readonly gray: string;
  readonly end: string;
}

export const SETTINGS_FRAME_NAMES = ['timer', 'display', 'appearance', 'notifications', 'privacy', 'advanced'] as const;
export type SettingsFrameName = (typeof SETTINGS_FRAME_NAMES)[number];

/** The Release 2 advanced frame's height. */
export const ADVANCED_TEST_MODES_HEIGHT = 1060;

/** The panel's height in each frame (the appearance frame is taller; Release 2's, with two more rows, more so). */
export const SETTINGS_FRAME_HEIGHT: Readonly<Record<SettingsFrameName, number>> = { timer: 800, display: 1220, appearance: 1160, notifications: 800, privacy: 800, advanced: 1000 };

/** Font families the frames name, and the site's name preview for each. */
